                ret.PreviewTransform = this.PreviewTransform.Combine(rhs.PreviewTransform);
                ret.SnapTemplate = this.SnapTemplate.Combine(rhs.SnapTemplate);
                ret.DefaultLayer = this.DefaultLayer.Combine(rhs.DefaultLayer);
                ret.XALG = this.XALG.Combine(rhs.XALG);
                ret.ObjectPlacementDefaults = new MaskItem<Exception?, IEnumerable<MaskItem<Exception?, ObjectPlacementDefault.ErrorMask?>>?>(Noggog.ExceptionExt.Combine(this.ObjectPlacementDefaults?.Overall, rhs.ObjectPlacementDefaults?.Overall), Noggog.ExceptionExt.Combine(this.ObjectPlacementDefaults?.Specific, rhs.ObjectPlacementDefaults?.Specific));
                ret.FULL = this.FULL.Combine(rhs.FULL);
                ret.Model = this.Model.Combine(rhs.Model, (l, r) => l.Combine(r));
                ret.ENLM = this.ENLM.Combine(rhs.ENLM);
                ret.ENLT = this.ENLT.Combine(rhs.ENLT);
                ret.ENLS = this.ENLS.Combine(rhs.ENLS);
                ret.AUUV = this.AUUV.Combine(rhs.AUUV);
                ret.ICON = this.ICON.Combine(rhs.ICON);
                ret.MICO = this.MICO.Combine(rhs.MICO);
                ret.PickUpSound = this.PickUpSound.Combine(rhs.PickUpSound);
                ret.PutDownSound = this.PutDownSound.Combine(rhs.PutDownSound);
                ret.Keywords = new MaskItem<Exception?, IEnumerable<(int Index, Exception Value)>?>(Noggog.ExceptionExt.Combine(this.Keywords?.Overall, rhs.Keywords?.Overall), Noggog.ExceptionExt.Combine(this.Keywords?.Specific, rhs.Keywords?.Specific));
                ret.FeaturedItemMessage = this.FeaturedItemMessage.Combine(rhs.FeaturedItemMessage);
                ret.ValueCurrency = this.ValueCurrency.Combine(rhs.ValueCurrency);
                ret.CNAM = this.CNAM.Combine(rhs.CNAM);
                ret.InventoryArt = this.InventoryArt.Combine(rhs.InventoryArt);
                ret.Quest = this.Quest.Combine(rhs.Quest);
                ret.BTOF = this.BTOF.Combine(rhs.BTOF);
                ret.DAMC = this.DAMC.Combine(rhs.DAMC);
                ret.Data = this.Data.Combine(rhs.Data, (l, r) => l.Combine(r));
                ret.Description = this.Description.Combine(rhs.Description);
                ret.DEST = this.DEST.Combine(rhs.DEST);
                ret.DMDC = this.DMDC.Combine(rhs.DMDC);
                ret.DMDS = this.DMDS.Combine(rhs.DMDS);
                ret.DNAM = this.DNAM.Combine(rhs.DNAM);
                ret.DSTA = this.DSTA.Combine(rhs.DSTA);
